#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_globalFreq;
uniform float amzp_speed;
uniform float amzp_freqRed;
uniform float amzp_freqGreen;
uniform float amzp_freqBlue;
uniform float amzp_phaseRed;
uniform float amzp_phaseGreen;
uniform float amzp_phaseBlue;
uniform float amzp_saturation;
uniform float amzp_brightness;
uniform float amzp_blend;


        float3 hash33(float3 p) {
            p = float3(dot(p, float3(127.1, 311.7, 74.7)),
                     dot(p, float3(269.5, 183.3, 246.1)),
                     dot(p, float3(113.5, 271.9, 124.6)));
            return -1.0 + 2.0 * fract(sin(p) * 43758.5453123);
        }


        float perlinNoise3D(float3 p) {
            float3 pi = floor(p);
            float3 pf = p - pi;


            float3 g000 = hash33(pi + float3(0.0, 0.0, 0.0));
            float3 g100 = hash33(pi + float3(1.0, 0.0, 0.0));
            float3 g010 = hash33(pi + float3(0.0, 1.0, 0.0));
            float3 g110 = hash33(pi + float3(1.0, 1.0, 0.0));
            float3 g001 = hash33(pi + float3(0.0, 0.0, 1.0));
            float3 g101 = hash33(pi + float3(1.0, 0.0, 1.0));
            float3 g011 = hash33(pi + float3(0.0, 1.0, 1.0));
            float3 g111 = hash33(pi + float3(1.0, 1.0, 1.0));


            float n000 = dot(g000, pf);
            float n100 = dot(g100, pf - float3(1.0, 0.0, 0.0));
            float n010 = dot(g010, pf - float3(0.0, 1.0, 0.0));
            float n110 = dot(g110, pf - float3(1.0, 1.0, 0.0));
            float n001 = dot(g001, pf - float3(0.0, 0.0, 1.0));
            float n101 = dot(g101, pf - float3(1.0, 0.0, 1.0));
            float n011 = dot(g011, pf - float3(0.0, 1.0, 1.0));
            float n111 = dot(g111, pf - float3(1.0, 1.0, 1.0));


            float3 u = pf * pf * (3.0 - 2.0 * pf);


            float nx00 = mix(n000, n100, u.x);
            float nx10 = mix(n010, n110, u.x);
            float nx01 = mix(n001, n101, u.x);
            float nx11 = mix(n011, n111, u.x);

            float nxy0 = mix(nx00, nx10, u.y);
            float nxy1 = mix(nx01, nx11, u.y);

            return mix(nxy0, nxy1, u.z);
        }


        float fbm3D(float3 p, int octaves) {
            float value = 0.0;
            float amplitude = 0.8;
            float frequency = 0.13;

            for (int i = 0; i < 4; i++) { 
                if (i >= octaves) break;
                value += amplitude * perlinNoise3D(p * frequency);
                amplitude *= 0.5;
                frequency *= 2.0;
            }

            return value;
        }

        void amzRender() {
            float2 suv = amzScreenNorm().xy;
            float2 uv = amzLayerNorm().xy;


            float aspect = layer.x / layer.y;
            uv = (uv - 0.5) * 2.0;
            uv.x *= aspect;


            float3 p = float3(uv * 3.0, time * amzp_speed);


            float noise = fbm3D(p, 4);


            noise = (noise + 1.0) * 0.5;




            float wave = noise * 6.28318 * amzp_globalFreq;


            float rC = 0.5 + 0.5 * sin(wave * amzp_freqRed + amzp_phaseRed);
            float gC = 0.5 + 0.5 * sin(wave * amzp_freqGreen + amzp_phaseGreen);
            float bC = 0.5 + 0.5 * sin(wave * amzp_freqBlue + amzp_phaseBlue);

            float3 col = float3(rC, gC, bC);


            float gray = dot(col, float3(0.299, 0.587, 0.114));
            col = mix(float3(gray), col, clamp(amzp_saturation, 0.0, 2.0));


            col *= amzp_brightness;

            float4 base = amzTexture(0, suv);
            float4 effectCol = float4(col * base.a, base.a);

            amzOutput = mix(base, effectCol, amzp_blend);
        }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

